   v[2] = sin(x[2]);
   v[3] = - v[2];
   v[4] = sin(x[3]);
   v[5] = v[0] * v[1] + v[3] * v[4];
   v[6] = cos(x[4]);
   v[7] = v[5] * v[6];
   v[8] = cos(x[5]);
   v[9] = sin(x[4]);
   v[5] = v[5] * v[9];
   v[10] = sin(x[5]);
