   v[5] = v[7] * v[10] + v[5] * v[8];
   v[13] = cos(x[7]);
   v[14] = - v[4];
   v[3] = v[0] * v[14] + v[3] * v[1];
   v[15] = sin(x[6]);
   v[16] = - v[15];
   v[17] = cos(x[6]);
   v[18] = v[3] * v[16] + v[5] * v[17];
   v[19] = sin(x[7]);
